-- Isolate the mutable policy inside this rollback-only fixture transaction.
update public.platform_settings set value=365,revision=1 where key='audit_retention_days';
create temp table initial_purge_count as select count(*)::integer as n from public.audit_logs where event_type='audit.retention_purged' and actor_user_id is null and metadata_redacted->>'actor_kind'='system';
create function pg_temp.actor(n integer) returns void language sql as $$ select set_config('request.jwt.claims',jsonb_build_object('sub',('f9100000-0000-4000-8000-'||lpad(n::text,12,'0')),'role','authenticated')::text,true); $$;
