('fa000000-0000-4000-8000-000000000002','f9200000-0000-4000-8000-000000000002',null,'security.fictional','ticket','f9400000-0000-4000-8000-000000000007','failure','{}'),
('fa000000-0000-4000-8000-000000000003',null,null,'security.fictional','platform_setting','fa000000-0000-4000-8000-000000000003','failure','{}'),
('fa000000-0000-4000-8000-000000000004','f9200000-0000-4000-8000-000000000001',null,'security.fictional','ticket','f9400000-0000-4000-8000-000000000001','success','{}');
select extensions.ok((select relrowsecurity from pg_class where oid='public.platform_settings'::regclass),'Settings RLS');
select extensions.is((select value from public.platform_settings where key='audit_retention_days'),365,'Default 365');
select extensions.is((select count(*)::integer from cron.job where jobname='securedesk-audit-retention' and active and username='postgres' and schedule='15 3 * * *'),1,'Daily owner schedule');
select extensions.ok(not (select prosecdef from pg_proc where oid='securedesk_private.purge_expired_audit(integer)'::regprocedure),'Retention never elevates callers');
select extensions.ok(not has_function_privilege('anon','public.audit_list(uuid,text,text,timestamptz,uuid)','EXECUTE'),'Anonymous audit RPC revoked');
select extensions.ok(not has_function_privilege('service_role','securedesk_private.purge_expired_audit(integer)','EXECUTE'),'Service role cannot purge');
select extensions.ok(not has_function_privilege('authenticated','securedesk_private.purge_expired_audit(integer)','EXECUTE'),'Authenticated cannot purge');
select extensions.ok(not has_table_privilege('authenticated','public.audit_logs','INSERT,UPDATE,DELETE'),'No direct audit writes');
select extensions.ok(not has_table_privilege('authenticated','public.platform_settings','INSERT,UPDATE,DELETE'),'No direct setting writes');
select pg_temp.actor(1);
select extensions.ok((public.audit_retention_settings()->>'days')::integer=365,'SA settings DTO');
select extensions.is(jsonb_array_length(public.audit_list(p_event_type=>'security.fictional')),3,'SA global and tenant security');
select extensions.ok(public.audit_list(p_event_type=>'ticket.status')::text not like '%Fictional secret sentinel%' and public.audit_list(p_event_type=>'ticket.status')::text not like '%Private free text%','DTO drops unknown/free text metadata');
