select extensions.throws_ok($t$select public.audit_list(p_outcome=>'pending')$t$,'22023',null,'Invalid outcome');
select extensions.throws_ok($t$select public.audit_list(p_before_at=>now())$t$,'22023',null,'Cursor needs ID');
