create function pg_temp.purge_fault() returns trigger language plpgsql as $$begin if new.event_type='audit.retention_purged' then raise exception 'Fictional purge audit failure';end if;return new;end;$$;
create trigger audit_purge_test_fault before insert on public.audit_logs for each row execute function pg_temp.purge_fault();
select extensions.throws_ok($t$select securedesk_private.purge_expired_audit()$t$,'P0001','Fictional purge audit failure','Purge audit failure rolls back removal');
select extensions.is((select count(*)::integer from public.audit_logs where event_type='audit.fictional'),3,'All old fixture rows restored');
drop trigger audit_purge_test_fault on public.audit_logs;
select extensions.is(securedesk_private.purge_expired_audit(1),1,'Bounded one old row removed');
select extensions.is(securedesk_private.purge_expired_audit(1),1,'Next old row removed');
select extensions.is(securedesk_private.purge_expired_audit(),0,'No early deletion, repeated purge no effect');
select extensions.ok(exists(select 1 from public.audit_logs where id='fb000000-0000-4000-8000-000000000003'),'Not yet expired audit preserved');
select extensions.is((select count(*)::integer from public.audit_logs where event_type='audit.retention_purged' and actor_user_id is null and metadata_redacted->>'actor_kind'='system'),(select n+2 from initial_purge_count),'System purge events');
select extensions.is((select count(*)::integer from public.tickets where id::text like 'f9400000%'),32,'Business tickets preserved by retention');
select set_config('securedesk_private.audit_retention_running','on',true);select set_config('securedesk_private.audit_retention_cutoff',(now()+interval '1 day')::text,true);select pg_temp.actor(1);
select extensions.throws_ok($t$delete from public.audit_logs where id='fa000000-0000-4000-8000-000000000001'$t$,'23514',null,'Forged flag with business JWT cannot delete');
set local role authenticated;
select extensions.throws_ok($t$select securedesk_private.purge_expired_audit()$t$,'42501',null,'Business SA cannot execute maintenance');
reset role;
select * from extensions.finish();rollback;
